Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  Focused solid
  <select id="solidType">
    <option>Right circular cylinder</option>
    <option>Solid sphere</option>
    <option>Solid cone</option>
