  </select>
</label>
<div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px">
  <button id="step0">(a)</button>
  <button id="step1">(b)</button>
  <button id="step2">(c)</button>
  <button id="step3">(d)</button>
</div>
<div style="font-size:11px;line-height:1.35;color:#333;margin-top:4px">
  Click the small panel tabs in the figure, or drag the solid to inspect its circular sweep.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// title → HTML label at top
// focused panel frame/spotlight → rounded-looking Rectangle PlaneGeometry fill + Line outline
// selector labels/thumbnails → clickable PlaneGeometry tabs + HTML labels
// axis of revolution → Line dark gray through 2D profile
// axis label → HTML label near profile axis
// rotation arrow → Line ellipse in YZ plane + ConeGeometry arrowhead
// cylinder profile → ShapeGeometry rectangle pale cyan + teal LineLoop
// cylinder solid → CylinderGeometry along X translucent cyan + Line circular end rims + central Line
// sphere profile → ShapeGeometry upper semicircle pale cyan + teal arc/diameter outline
// sphere solid → SphereGeometry translucent cyan + soft white highlight mesh + central Line
// cone profile → ShapeGeometry right triangle pale cyan + teal LineLoop
// cone solid → ConeGeometry along X translucent cyan + base circular Line rim + generator Lines + central Line
// hollow profile → ShapeGeometry offset rectangle pale cyan + teal LineLoop
// hollow cylinder solid → custom BufferGeometry tube with outer/inner surfaces and annular end faces + four circular Line rims + central Line
// boxed name label → white PlaneGeometry rectangle + gray LineLoop + HTML label
// panel letter → italic HTML label
// ghost copies → cloned profile ShapeGeometry meshes rotating around X axis
// swept preview → translucent revolution solid at profile axis

const FIG = {
  teal: 0x21b8bd,
  pale: 0xc9e9e7,
  cyan: 0x27c1c5,
  dark: 0x222222,
  charcoal: '#252525',
  gray: 0xbfc1c4,
  profileY: 1.28,
  solidY: -0.78,
  selected: 'Right circular cylinder',
  animating: false,
  theta: 0,
  root: new THREE.Group(),
  labels: [],
  ghostRoot: null,
  sweepRoot: null
};

scene.add(FIG.root);
scene.add(new THREE.AmbientLight(0xffffff, 0.68));
const figLight = new THREE.DirectionalLight(0xffffff, 0.85);
figLight.position.set(3, 4, 5);
scene.add(figLight);

const SOLIDS = [
  {
    name: 'Right circular cylinder',
    short: 'Cylinder',
    letter: '(a)',
    title: 'Right circular cylinder',
    body: 'A rectangle with one edge on the axis sweeps out a right circular cylinder. Its height above the axis becomes the radius.'
  },
  {
    name: 'Solid sphere',
    short: 'Sphere',
    letter: '(b)',
    title: 'Solid sphere',
    body: 'A semicircular region rotated about its diameter fills a solid sphere.'
  },
  {
    name: 'Solid cone',
    short: 'Cone',
    letter: '(c)',
    title: 'Solid cone',
    body: 'A right triangle rotated about one leg creates a cone. The slanted side traces the lateral surface.'
  },
  {
    name: 'Hollowed right circular cylinder',
    short: 'Hollow cylinder',
    letter: '(d)',
    title: 'Hollowed right circular cylinder',
    body: 'An offset rectangle rotates into a tube. Its lower and upper distances from the axis become the inner and outer radii.'
  }
];

function figMat(color, opacity, side = THREE.DoubleSide) {
  return new THREE.MeshPhongMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side,
    shininess: 45,
    depthWrite: opacity >= 0.9
  });
}

function basicMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 0.9
  });
}

function makeLine(points, color = FIG.dark, closed = false) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color });
  return closed ? new THREE.LineLoop(geom, mat) : new THREE.Line(geom, mat);
}

function rectShape(x0, y0, x1, y1) {
  const s = new THREE.Shape();
  s.moveTo(x0, y0);
  s.lineTo(x1, y0);
  s.lineTo(x1, y1);
  s.lineTo(x0, y1);
  s.lineTo(x0, y0);
  return s;
}

function makeBox(center, w, h, fill = 0xffffff, stroke = FIG.gray, opacity = 0.96) {
  const g = new THREE.Group();
  const plane = new THREE.Mesh(new THREE.PlaneGeometry(w, h), basicMat(fill, opacity));
  plane.position.set(center.x, center.y, center.z - 0.015);
  g.add(plane);
  const pts = [
    new THREE.Vector3(center.x - w / 2, center.y - h / 2, center.z),
    new THREE.Vector3(center.x + w / 2, center.y - h / 2, center.z),
    new THREE.Vector3(center.x + w / 2, center.y + h / 2, center.z),
    new THREE.Vector3(center.x - w / 2, center.y + h / 2, center.z)
  ];
  g.add(makeLine(pts, stroke, true));
  return g;
}

function circleYZ(x, r, color = FIG.teal, segments = 128) {
  const pts = [];
  for (let i = 0; i < segments; i++) {
    const a = 2 * Math.PI * i / segments;
    pts.push(new THREE.Vector3(x, r * Math.cos(a), r * Math.sin(a)));
  }
  return makeLine(pts, color, true);
}

function addAxis(parent, x0, x1, y = 0, z = 0, color = FIG.dark) {
  parent.add(makeLine([
    new THREE.Vector3(x0, y, z),
    new THREE.Vector3(x1, y, z)
  ], color));
}

function makeRotationArrow() {
  const g = new THREE.Group();
  const pts = [];
  const x = 2.64;
  for (let i = 0; i <= 70; i++) {
    const a = -0.25 * Math.PI + 1.72 * Math.PI * (i / 70);
    pts.push(new THREE.Vector3(x, 0.12 + 0.38 * Math.cos(a), 0.22 * Math.sin(a)));
  }
  g.add(makeLine(pts, FIG.dark));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.16, 18), basicMat(FIG.dark));
  cone.position.set(x, -0.28, 0.055);
  cone.rotation.z = 0;
  g.add(cone);
  return g;
}

function profileShapeGroup(type, opacity = 0.72, outlineOpacity = 1) {
  const g = new THREE.Group();
  let shape, outlinePts;

  if (type === 'Right circular cylinder') {
    shape = rectShape(-2, 0, 2, 1);
    outlinePts = [
      new THREE.Vector3(-2, 0, 0), new THREE.Vector3(2, 0, 0),
      new THREE.Vector3(2, 1, 0), new THREE.Vector3(-2, 1, 0)
    ];
  } else if (type === 'Solid sphere') {
    shape = new THREE.Shape();
    shape.moveTo(-1.35, 0);
    for (let i = 0; i <= 72; i++) {
      const a = Math.PI - Math.PI * (i / 72);
      shape.lineTo(1.35 * Math.cos(a), 1.35 * Math.sin(a));
    }
    shape.lineTo(-1.35, 0);
    outlinePts = [];
    for (let i = 0; i <= 72; i++) {
      const a = Math.PI - Math.PI * (i / 72);
      outlinePts.push(new THREE.Vector3(1.35 * Math.cos(a), 1.35 * Math.sin(a), 0));
    }
    outlinePts.push(new THREE.Vector3(-1.35, 0, 0));
  } else if (type === 'Solid cone') {
    shape = new THREE.Shape();
    shape.moveTo(-2, 0);
    shape.lineTo(2, 0);
    shape.lineTo(2, 1.05);
    shape.lineTo(-2, 0);
    outlinePts = [
      new THREE.Vector3(-2, 0, 0),
      new THREE.Vector3(2, 0, 0),
      new THREE.Vector3(2, 1.05, 0)
    ];
  } else {
    shape = rectShape(-2, 0.55, 2, 1.05);
    outlinePts = [
      new THREE.Vector3(-2, 0.55, 0), new THREE.Vector3(2, 0.55, 0),
      new THREE.Vector3(2, 1.05, 0), new THREE.Vector3(-2, 1.05, 0)
    ];
  }

  const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape), basicMat(FIG.pale, opacity));
  g.add(fill);

  const line = makeLine(outlinePts, FIG.teal, type !== 'Solid sphere');
  line.material.transparent = outlineOpacity < 1;
  line.material.opacity = outlineOpacity;
  g.add(line);
  return g;
}

function tubeGeometry(length = 4, inner = 0.55, outer = 1.05, seg = 128) {
  const positions = [];
  const xL = -length / 2, xR = length / 2;

  function v(x, r, a) {
    positions.push(x, r * Math.cos(a), r * Math.sin(a));
  }

  for (let i = 0; i < seg; i++) {
    const a0 = 2 * Math.PI * i / seg;
    const a1 = 2 * Math.PI * (i + 1) / seg;

    v(xL, outer, a0); v(xR, outer, a0); v(xR, outer, a1);
    v(xL, outer, a0); v(xR, outer, a1); v(xL, outer, a1);

    v(xL, inner, a1); v(xR, inner, a1); v(xR, inner, a0);
    v(xL, inner, a1); v(xR, inner, a0); v(xL, inner, a0);

    v(xR, inner, a0); v(xR, inner, a1); v(xR, outer, a1);
    v(xR, inner, a0); v(xR, outer, a1); v(xR, outer, a0);

    v(xL, outer, a0); v(xL, outer, a1); v(xL, inner, a1);
    v(xL, outer, a0); v(xL, inner, a1); v(xL, inner, a0);
  }

  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

function solidGroup(type, opts = {}) {
  const preview = !!opts.preview;
  const g = new THREE.Group();
  const op = preview ? 0.18 : 0.62;
  const mat = figMat(FIG.cyan, op);

  if (type === 'Right circular cylinder') {
    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 4, 96, 1, false), mat);
    cyl.rotation.z = Math.PI / 2;
    g.add(cyl);
    g.add(circleYZ(-2, 1, FIG.teal));
    g.add(circleYZ(2, 1, FIG.teal));
  } else if (type === 'Solid sphere') {
    const s = new THREE.Mesh(new THREE.SphereGeometry(1.35, 80, 48), mat);
    g.add(s);
    const hi = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 12), basicMat(0xffffff, preview ? 0.08 : 0.28));
    hi.position.set(-0.42, 0.55, 0.72);
    hi.scale.set(1.55, 0.9, 0.45);
    g.add(hi);
  } else if (type === 'Solid cone') {
    const cone = new THREE.Mesh(new THREE.ConeGeometry(1.05, 4, 96, 1, false), mat);
    cone.rotation.z = Math.PI / 2;
    g.add(cone);
    g.add(circleYZ(2, 1.05, FIG.teal));
    g.add(makeLine([new THREE.Vector3(-2, 0, 0), new THREE.Vector3(2, 1.05, 0)], FIG.teal));
    g.add(makeLine([new THREE.Vector3(-2, 0, 0), new THREE.Vector3(2, -1.05, 0)], FIG.teal));
  } else {
    const tube = new THREE.Mesh(tubeGeometry(4, 0.55, 1.05, 128), mat);
    g.add(tube);
    g.add(circleYZ(-2, 1.05, FIG.teal));
    g.add(circleYZ(2, 1.05, FIG.teal));
    g.add(circleYZ(-2, 0.55, FIG.teal));
    g.add(circleYZ(2, 0.55, FIG.teal));
  }

  if (!preview) addAxis(g, -2.85, 2.85, 0, 0, FIG.dark);
  return g;
}

function clearFigure() {
  FIG.root.clear();
  for (const entry of FIG.labels) {
    entry.div.remove();
    const i = _labels.indexOf(entry);
    if (i >= 0) _labels.splice(i, 1);
  }
  FIG.labels = [];
  if (typeof _interactiveObjects !== 'undefined') _interactiveObjects.length = 0;
}

function addFigLabel(html, pos, opts = {}) {
  const e = addLabel(html, pos, opts);
  FIG.labels.push(e);
  return e;
}

function selectorGroup() {
  const g = new THREE.Group();
  const xs = [-2.35, -0.78, 0.78, 2.35];
  SOLIDS.forEach((s, i) => {
    const active = s.name === FIG.selected;
    const tab = makeBox(new THREE.Vector3(xs[i], -2.95, 0), 1.34, 0.34, active ? FIG.pale : 0xffffff, active ? FIG.teal : FIG.gray, 0.97);
    g.add(tab);
    registerInteractive(tab, {
      title: s.title,
      tooltip: `Click to focus ${s.letter}`,
      body: s.body,
      onClick: () => setSolid(s.name)
    });
  });
  return g;
}

function buildFigure() {
  clearFigure();

  const selectedInfo = SOLIDS.find(s => s.name === FIG.selected);
  const frame = makeBox(new THREE.Vector3(0, -0.12, -0.08), 6.05, 5.35, 0xffffff, 0xe6e6e6, 0.02);
  FIG.root.add(frame);

  const profile = new THREE.Group();
  profile.position.y = FIG.profileY;
  addAxis(profile, -2.8, 2.8);
  profile.add(profileShapeGroup(FIG.selected, 0.72));
  profile.add(makeRotationArrow());

  FIG.ghostRoot = new THREE.Group();
  FIG.ghostRoot.visible = FIG.animating;
  const ghostAngles = [0, Math.PI / 4, Math.PI / 2, 3 * Math.PI / 4, Math.PI, 5 * Math.PI / 4];
  ghostAngles.forEach(a => {
    const ghost = profileShapeGroup(FIG.selected, 0.09, 0.32);
    ghost.rotation.x = a;
    FIG.ghostRoot.add(ghost);
  });
  const movingGhost = profileShapeGroup(FIG.selected, 0.28, 0.78);
  movingGhost.userData.movingGhost = true;
  FIG.ghostRoot.add(movingGhost);
  profile.add(FIG.ghostRoot);

  FIG.sweepRoot = solidGroup(FIG.selected, { preview: true });
  FIG.sweepRoot.visible = FIG.animating;
  profile.add(FIG.sweepRoot);

  FIG.root.add(profile);
  registerInteractive(profile, {
    title: 'Generating region',
    tooltip: '2D region to be revolved',
    body: 'This flat region is swept around the horizontal axis to create the solid below.'
  });

  const solid = solidGroup(FIG.selected);
  solid.position.y = FIG.solidY;
  FIG.root.add(solid);
  registerInteractive(solid, {
    title: selectedInfo.title,
    tooltip: 'Drag to rotate this solid',
    body: selectedInfo.body
  });

  let boxW = 2.35;
  if (FIG.selected === 'Right circular cylinder') boxW = 2.72;
  if (FIG.selected === 'Hollowed right circular cylinder') boxW = 3.52;
  if (FIG.selected === 'Solid cone') boxW = 1.65;
  if (FIG.selected === 'Solid sphere') boxW = 1.92;
  FIG.root.add(makeBox(new THREE.Vector3(0, -2.36, 0), boxW, 0.48, 0xffffff, FIG.gray, 0.96));
  FIG.root.add(selectorGroup());

  const bounds = new THREE.Group();
  const m = basicMat(0xffffff, 0.001);
  [[0, 2.72, 0], [0, -3.12, 0], [-3.05, 0, 0], [3.05, 0, 0]].forEach(p => {
    const dot = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.025, 0.025), m);
    dot.position.set(p[0], p[1], p[2]);
    bounds.add(dot);
  });
  FIG.root.add(bounds);

  setCameraView({
    projection: 'orthographic',
    axisScreenAngles: { x: 30, z: 30 },
    rollDeg: 0,
    heightFraction: 0.72
  });

  addFigLabel('Some Familiar Solids of Revolution', new THREE.Vector3(0, 2.68, 0), {
    fontSize: '24px',
    color: FIG.charcoal,
    offset: [0, -4]
  });
  addFigLabel('Axis of revolution', new THREE.Vector3(-1.82, FIG.profileY - 0.36, 0), {
    fontSize: '15px',
    color: FIG.charcoal,
    offset: [0, 0]
  });
  addFigLabel(selectedInfo.name, new THREE.Vector3(0, -2.36, 0), {
    fontSize: FIG.selected === 'Hollowed right circular cylinder' ? '17px' : '20px',
    color: FIG.charcoal,
    background: 'rgba(255,255,255,0)'
  });
  addFigLabel(`<i>${selectedInfo.letter}</i>`, new THREE.Vector3(0, -2.68, 0), {
    fontSize: '22px',
    color: '#111',
    offset: [0, 8]
  });

  const xs = [-2.35, -0.78, 0.78, 2.35];
  SOLIDS.forEach((s, i) => {
    addFigLabel(`${s.letter} ${s.short}`, new THREE.Vector3(xs[i], -2.95, 0), {
      fontSize: '10px',
      bold: s.name === FIG.selected,
      color: s.name === FIG.selected ? '#057c82' : FIG.charcoal
    });
  });

  updateUiState();
}

function updateUiState() {
  const solidSel = document.getElementById('solidType');
  const animSel = document.getElementById('rotationAnimation');
  if (solidSel) solidSel.value = FIG.selected;
  if (animSel) animSel.value = FIG.animating ? 'On' : 'Off';
}

function setSolid(name) {
  FIG.selected = name;
  buildFigure();
}

function setAnimation(on) {
  FIG.animating = !!on;
  if (FIG.ghostRoot) FIG.ghostRoot.visible = FIG.animating;
  if (FIG.sweepRoot) FIG.sweepRoot.visible = FIG.animating;
  updateUiState();
}

document.getElementById('solidType').addEventListener('change', e => setSolid(e.target.value));
document.getElementById('rotationAnimation').addEventListener('change', e => setAnimation(e.target.value === 'On'));

const DEMO = [
  {
    title: 'Rectangle to cylinder',
    narration: 'The rectangle sits with its lower edge on the axis of revolution. Revolving it sweeps out a right circular cylinder whose radius is the rectangle height.',
    state: { solidType: 'Right circular cylinder', rotationAnimation: 'On' }
  },
  {
    title: 'Semicircle to sphere',
    narration: 'The semicircle has its diameter on the axis. Rotating the semicircular region around that diameter fills a solid sphere.',
    state: { solidType: 'Solid sphere', rotationAnimation: 'On' }
  },
  {
    title: 'Triangle to cone',
    narration: 'The triangular region has one side on the axis. As it turns, the slanted edge traces the cone’s lateral surface and the vertical side traces the circular base.',
    state: { solidType: 'Solid cone', rotationAnimation: 'On' }
  },
  {
