// @FIGURE_CODE_BEGIN
// title → HTML label centered above all four panels
// top axes of revolution → black horizontal Lines, one per panel
// top rotation arrows → black ellipse Lines plus triangular ShapeGeometry arrowheads
// cylinder generating region → pale cyan rectangular ShapeGeometry with teal LineLoop outline
// sphere generating region → pale cyan semicircular ShapeGeometry with teal arc/diameter Line
// cone generating region → pale cyan triangular ShapeGeometry with teal LineLoop outline
// hollow cylinder generating region → pale cyan offset rectangular ShapeGeometry with teal LineLoop outline
// cylinder solid → cyan rectangular body PlaneGeometry, left/right ellipse ShapeGeometry caps, teal ellipse Lines, black axis Line
// sphere solid → cyan circular ShapeGeometry disk, translucent white highlight circles, black axis Line
// cone solid → cyan triangular ShapeGeometry body, right ellipse ShapeGeometry cap, teal generator Lines and ellipse Line, black axis Line
// hollow cylinder solid → cyan rectangular outer/inner body PlaneGeometry, annular ellipse ShapeGeometry end faces with inner/outer ellipse Lines, black axis Line
// boxed captions → white PlaneGeometry rectangles with gray LineLoop borders plus HTML labels
// panel letters → italic HTML labels below each caption
// selected animation ghosts → pale cloned generating ShapeGeometry regions rotating about the x-axis
// panel hit areas → invisible PlaneGeometry rectangles registered as interactive panels

const FIG = {
  teal: 0x21b8bd,
  pale: 0xc9e9e7,
  cyan: 0x23bec4,
  dark: 0x252525,
  gray: 0xbfc1c4,
  charcoal: '#252525',
  selected: 'Right circular cylinder',
  animating: false,
  theta: 0,
  root: new THREE.Group(),
  labels: [],
  animGhost: null
};

scene.add(FIG.root);

const SOLIDS = [
  {
    name: 'Right circular cylinder',
    short: 'Right circular cylinder',
    letter: '(a)',
    body: 'A rectangle with one side on the axis of revolution sweeps out a right circular cylinder.'
  },
  {
    name: 'Solid sphere',
    short: 'Solid sphere',
    letter: '(b)',
    body: 'A semicircular region revolved about its diameter fills a solid sphere.'
  },
  {
    name: 'Solid cone',
    short: 'Solid cone',
    letter: '(c)',
    body: 'A triangular region revolved about one leg forms a solid cone.'
  },
  {
    name: 'Hollowed right circular cylinder',
    short: 'Hollowed right<br>circular cylinder',
    letter: '(d)',
    body: 'An offset rectangle revolved about the axis creates a hollowed right circular cylinder.'
  }
];

const PANEL_X = [-3.15, -1.05, 1.05, 3.15];
const TOP_Y = 1.02;
const SOLID_Y = -0.48;
const CAPTION_Y = -1.46;
const LETTER_Y = -1.93;

function basicMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 1
  });
}

function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
}

function makeLine(points, color = FIG.dark, closed = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  return closed ? new THREE.LineLoop(geom, lineMat(color, opacity)) : new THREE.Line(geom, lineMat(color, opacity));
}

function rectMesh(cx, cy, w, h, color, opacity = 1, z = 0) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), basicMat(color, opacity));
  mesh.position.set(cx, cy, z);
  return mesh;
}

function rectLine(cx, cy, w, h, color = FIG.gray, z = 0.01) {
  return makeLine([
    new THREE.Vector3(cx - w / 2, cy - h / 2, z),
    new THREE.Vector3(cx + w / 2, cy - h / 2, z),
    new THREE.Vector3(cx + w / 2, cy + h / 2, z),
    new THREE.Vector3(cx - w / 2, cy + h / 2, z)
  ], color, true);
}

function shapeMesh(shape, color, opacity = 1, z = 0) {
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), basicMat(color, opacity));
  mesh.position.z = z;
  return mesh;
}

function ellipseShape(cx, cy, rx, ry) {
  const s = new THREE.Shape();
  s.absellipse(cx, cy, rx, ry, 0, Math.PI * 2, false, 0);
  return s;
}

function ellipseMesh(cx, cy, rx, ry, color, opacity = 1, z = 0) {
  return shapeMesh(ellipseShape(cx, cy, rx, ry), color, opacity, z);
}

function ellipseLine(cx, cy, rx, ry, color = FIG.teal, z = 0.02, opacity = 1, segments = 96) {
  const pts = [];
  for (let i = 0; i < segments; i++) {
    const a = Math.PI * 2 * i / segments;
    pts.push(new THREE.Vector3(cx + rx * Math.cos(a), cy + ry * Math.sin(a), z));
  }
  return makeLine(pts, color, true, opacity);
}

function annulusEllipseMesh(cx, cy, rxO, ryO, rxI, ryI, color, opacity = 1, z = 0) {
  const outer = new THREE.Shape();
  outer.absellipse(cx, cy, rxO, ryO, 0, Math.PI * 2, false, 0);
  const hole = new THREE.Path();
  hole.absellipse(cx, cy, rxI, ryI, 0, Math.PI * 2, true, 0);
  outer.holes.push(hole);
  return shapeMesh(outer, color, opacity, z);
}

function triangleMesh(points2, color, opacity = 1, z = 0) {
  const s = new THREE.Shape();
  s.moveTo(points2[0][0], points2[0][1]);
  for (let i = 1; i < points2.length; i++) s.lineTo(points2[i][0], points2[i][1]);
  s.lineTo(points2[0][0], points2[0][1]);
  return shapeMesh(s, color, opacity, z);
}

function addFigLabel(html, pos, opts = {}) {
  const e = addLabel(html, pos, opts);
  FIG.labels.push(e);
  return e;
}

function clearFigure() {
  FIG.root.clear();
  for (const entry of FIG.labels) {
    entry.div.remove();
    const idx = _labels.indexOf(entry);
    if (idx >= 0) _labels.splice(idx, 1);
  }
  FIG.labels = [];
  if (typeof _interactiveObjects !== 'undefined') _interactiveObjects.length = 0;
  FIG.animGhost = null;
}

function makeRotationArrowLocal() {
  const g = new THREE.Group();
  const cx = 0.86, cy = 0.02, rx = 0.07, ry = 0.27;
  const pts = [];
  for (let i = 0; i <= 72; i++) {
    const a = -1.35 * Math.PI + 1.76 * Math.PI * (i / 72);
    pts.push(new THREE.Vector3(cx + rx * Math.cos(a), cy + ry * Math.sin(a), 0.025));
  }
  g.add(makeLine(pts, FIG.dark, false));
  const head = new THREE.Shape();
  head.moveTo(cx + 0.04, cy - 0.14);
  head.lineTo(cx + 0.12, cy - 0.23);
  head.lineTo(cx + 0.02, cy - 0.20);
  head.lineTo(cx + 0.04, cy - 0.14);
  g.add(shapeMesh(head, FIG.dark, 1, 0.03));
  return g;
}

function makeTopAxis() {
  return makeLine([
    new THREE.Vector3(-0.95, 0, 0.02),
    new THREE.Vector3(0.98, 0, 0.02)
  ], FIG.dark);
}

function profileRegion(type, opacity = 0.72, outlineOpacity = 1) {
  const g = new THREE.Group();

  if (type === 'Right circular cylinder') {
    const s = new THREE.Shape();
    s.moveTo(-0.64, 0);
    s.lineTo(0.64, 0);
    s.lineTo(0.64, 0.62);
    s.lineTo(-0.64, 0.62);
    s.lineTo(-0.64, 0);
    g.add(shapeMesh(s, FIG.pale, opacity, 0.01));
    g.add(makeLine([
      new THREE.Vector3(-0.64, 0, 0.04),
      new THREE.Vector3(0.64, 0, 0.04),
      new THREE.Vector3(0.64, 0.62, 0.04),
      new THREE.Vector3(-0.64, 0.62, 0.04)
    ], FIG.teal, true, outlineOpacity));
  }

  if (type === 'Solid sphere') {
    const r = 0.62;
    const s = new THREE.Shape();
    s.moveTo(-r, 0);
    for (let i = 0; i <= 72; i++) {
      const a = Math.PI - Math.PI * i / 72;
      s.lineTo(r * Math.cos(a), r * Math.sin(a));
    }
    s.lineTo(-r, 0);
    g.add(shapeMesh(s, FIG.pale, opacity, 0.01));
    const pts = [];
    for (let i = 0; i <= 72; i++) {
      const a = Math.PI - Math.PI * i / 72;
      pts.push(new THREE.Vector3(r * Math.cos(a), r * Math.sin(a), 0.04));
    }
    pts.push(new THREE.Vector3(-r, 0, 0.04));
    g.add(makeLine(pts, FIG.teal, false, outlineOpacity));
  }

  if (type === 'Solid cone') {
    g.add(triangleMesh([[-0.62, 0], [0.64, 0], [0.64, 0.62]], FIG.pale, opacity, 0.01));
    g.add(makeLine([
      new THREE.Vector3(-0.62, 0, 0.04),
      new THREE.Vector3(0.64, 0, 0.04),
      new THREE.Vector3(0.64, 0.62, 0.04)
    ], FIG.teal, true, outlineOpacity));
  }

  if (type === 'Hollowed right circular cylinder') {
    const s = new THREE.Shape();
    s.moveTo(-0.64, 0.36);
    s.lineTo(0.64, 0.36);
    s.lineTo(0.64, 0.64);
    s.lineTo(-0.64, 0.64);
    s.lineTo(-0.64, 0.36);
    g.add(shapeMesh(s, FIG.pale, opacity, 0.01));
    g.add(makeLine([
      new THREE.Vector3(-0.64, 0.36, 0.04),
      new THREE.Vector3(0.64, 0.36, 0.04),
      new THREE.Vector3(0.64, 0.64, 0.04),
      new THREE.Vector3(-0.64, 0.64, 0.04)
    ], FIG.teal, true, outlineOpacity));
  }

  return g;
}

function topPanel(type, index) {
  const g = new THREE.Group();
  g.position.set(PANEL_X[index], TOP_Y, 0);
  g.add(makeTopAxis());
  g.add(profileRegion(type));
  g.add(makeRotationArrowLocal());

  if (type === FIG.selected && FIG.animating) {
    const ghostAngles = [Math.PI / 4, Math.PI / 2, 3 * Math.PI / 4];
    ghostAngles.forEach(a => {
      const ghost = profileRegion(type, 0.12, 0.28);
      ghost.rotation.x = a;
      g.add(ghost);
    });
    FIG.animGhost = profileRegion(type, 0.34, 0.9);
    FIG.animGhost.position.z = 0.075;
    g.add(FIG.animGhost);
  }

  return g;
}

function solidAxis(y = 0, z = 0.08) {
  return makeLine([
    new THREE.Vector3(-0.96, y, z),
    new THREE.Vector3(0.96, y, z)
  ], FIG.dark, false, 0.95);
}

function cylinderSolid() {
  const g = new THREE.Group();
  g.add(rectMesh(0, 0, 1.45, 0.86, FIG.cyan, 0.62, 0.01));
  g.add(rectMesh(0.02, 0.07, 1.18, 0.14, 0xffffff, 0.16, 0.04));
  g.add(ellipseMesh(-0.72, 0, 0.19, 0.43, FIG.cyan, 0.54, 0.05));
  g.add(ellipseMesh(0.72, 0, 0.19, 0.43, FIG.pale, 0.82, 0.07));
  g.add(ellipseLine(-0.72, 0, 0.19, 0.43, FIG.teal, 0.08, 0.45));
  g.add(ellipseLine(0.72, 0, 0.19, 0.43, FIG.teal, 0.09, 1));
  g.add(solidAxis());
  return g;
}

function sphereSolid() {
  const g = new THREE.Group();
  g.add(ellipseMesh(0, 0, 0.62, 0.62, FIG.cyan, 0.75, 0.03));
  g.add(ellipseMesh(-0.18, 0.20, 0.26, 0.22, 0xffffff, 0.20, 0.06));
  g.add(ellipseMesh(-0.31, 0.29, 0.12, 0.10, 0xffffff, 0.18, 0.07));
  g.add(solidAxis(0, 0.09));
  return g;
}

function coneSolid() {
  const g = new THREE.Group();
  g.add(triangleMesh([[-0.72, 0], [0.72, 0.43], [0.72, -0.43]], FIG.cyan, 0.62, 0.01));
  g.add(ellipseMesh(0.72, 0, 0.19, 0.43, FIG.pale, 0.78, 0.05));
  g.add(makeLine([
    new THREE.Vector3(-0.72, 0, 0.07),
    new THREE.Vector3(0.72, 0.43, 0.07)
  ], FIG.teal));
  g.add(makeLine([
    new THREE.Vector3(-0.72, 0, 0.07),
    new THREE.Vector3(0.72, -0.43, 0.07)
  ], FIG.teal));
  g.add(ellipseLine(0.72, 0, 0.19, 0.43, FIG.teal, 0.08, 1));
  g.add(solidAxis());
  return g;
}

function hollowCylinderSolid() {
  const g = new THREE.Group();
  g.add(rectMesh(0, 0, 1.45, 0.86, FIG.cyan, 0.56, 0.01));
  g.add(rectMesh(0, 0, 1.30, 0.42, 0x149da4, 0.22, 0.035));
  g.add(annulusEllipseMesh(-0.72, 0, 0.20, 0.43, 0.10, 0.22, FIG.pale, 0.46, 0.06));
  g.add(annulusEllipseMesh(0.72, 0, 0.20, 0.43, 0.10, 0.22, FIG.pale, 0.88, 0.08));
  g.add(ellipseMesh(0.72, 0, 0.10, 0.22, 0x159aa1, 0.62, 0.09));
  g.add(ellipseMesh(-0.72, 0, 0.10, 0.22, 0x159aa1, 0.30, 0.07));
  g.add(ellipseLine(-0.72, 0, 0.20, 0.43, FIG.teal, 0.10, 0.45));
  g.add(ellipseLine(0.72, 0, 0.20, 0.43, FIG.teal, 0.11, 1));
  g.add(ellipseLine(-0.72, 0, 0.10, 0.22, FIG.teal, 0.12, 0.36));
  g.add(ellipseLine(0.72, 0, 0.10, 0.22, FIG.teal, 0.13, 0.95));
  g.add(solidAxis());
  return g;
}

function solidPanel(type, index) {
  const g = new THREE.Group();
  g.position.set(PANEL_X[index], SOLID_Y, 0);
  if (type === 'Right circular cylinder') g.add(cylinderSolid());
  if (type === 'Solid sphere') g.add(sphereSolid());
  if (type === 'Solid cone') g.add(coneSolid());
  if (type === 'Hollowed right circular cylinder') g.add(hollowCylinderSolid());
  return g;
}

function captionBox(index, info) {
  const g = new THREE.Group();
  const w = info.name === 'Right circular cylinder' ? 1.78
    : info.name === 'Hollowed right circular cylinder' ? 1.36
      : info.name === 'Solid sphere' ? 1.08 : 0.95;
  const h = info.name === 'Hollowed right circular cylinder' ? 0.62 : 0.36;
  g.add(rectMesh(PANEL_X[index], CAPTION_Y, w, h, 0xffffff, 0.98, 0.0));
  g.add(rectLine(PANEL_X[index], CAPTION_Y, w, h, FIG.gray, 0.04));
  return g;
}

function addLabels() {
  addFigLabel('Some Familiar Solids of Revolution', new THREE.Vector3(0, 2.08, 0), {
    fontSize: '30px',
    color: FIG.charcoal
  });

  addFigLabel('Axis of revolution', new THREE.Vector3(PANEL_X[0] - 0.30, TOP_Y - 0.22, 0), {
    fontSize: '25px',
    color: FIG.charcoal,
    offset: [-42, 5]
  });

  SOLIDS.forEach((info, i) => {
    addFigLabel(info.short, new THREE.Vector3(PANEL_X[i], CAPTION_Y, 0), {
      fontSize: info.name === 'Hollowed right circular cylinder' ? '24px' : '26px',
      color: FIG.charcoal
    });
    addFigLabel(`<i>${info.letter}</i>`, new THREE.Vector3(PANEL_X[i], LETTER_Y, 0), {
      fontSize: '30px',
      color: '#111'
    });
  });
}

function addPanelHitArea(info, index) {
  const hit = rectMesh(PANEL_X[index], 0.02, 1.92, 3.38, 0xffffff, 0.001, 0.2);
  hit.material.depthWrite = false;
  FIG.root.add(hit);
  registerInteractive(hit, {
    title: info.name,
    tooltip: `Click to focus ${info.letter}`,
    body: info.body,
    onClick: () => {
      setSolid(info.name);
      showPopup(info.name, info.body);
    }
  });
}

function addBoundsForFit() {
  const m = basicMat(0xffffff, 0.001);
  m.depthWrite = false;
  [
    [-4.08, -2.13, 0], [4.08, -2.13, 0],
    [-4.08, 2.26, 0], [4.08, 2.26, 0]
  ].forEach(p => {
    const b = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.025, 0.025), m);
    b.position.set(p[0], p[1], p[2]);
    FIG.root.add(b);
  });
}

function buildFigure() {
  clearFigure();

