// @FIGURE_CODE_BEGIN
// title → HTML label centered above all panels
// top axes of revolution → black horizontal Lines, one per panel
// top rotation arrows → black curved Lines plus filled ShapeGeometry arrowheads
// cylinder generating region → pale cyan rectangular ShapeGeometry with teal LineLoop outline
// sphere generating region → pale cyan semicircular ShapeGeometry with teal arc/diameter Line
// cone generating region → pale cyan triangular ShapeGeometry with teal LineLoop outline
// hollow cylinder generating region → pale cyan offset rectangular ShapeGeometry with teal LineLoop outline
// cylinder solid → true CylinderGeometry side shell plus CircleGeometry end caps, circular LineLoops, and axis Line
// sphere solid → true SphereGeometry with Phong lighting, subtle highlight patch, and axis Line
// cone solid → true ConeGeometry side shell plus CircleGeometry base cap, circular LineLoop, generator Lines, and axis Line
// hollow cylinder solid → true outer CylinderGeometry, inner BackSide CylinderGeometry, RingGeometry annular end caps, circular LineLoops, and axis Line
// boxed captions → white PlaneGeometry rectangles with gray LineLoop borders plus HTML labels
// panel letters → italic HTML labels below each caption
// selected animation ghosts → pale cloned generating ShapeGeometry regions rotating about the x-axis
// panel hit areas → invisible PlaneGeometry rectangles registered as interactive panels

const FIG = {
  teal: 0x22b9bf,
  pale: 0xcfeceb,
  cyan: 0x1fbec5,
  cyanDark: 0x139aa2,
  dark: 0x242124,
  gray: 0xbfc1c4,
  charcoal: '#242124',
  selected: 'Right circular cylinder',
  animating: false,
  theta: 0,
  root: new THREE.Group(),
  labels: [],
  animGhost: null,
  lightsAdded: false
};

scene.add(FIG.root);

if (!FIG.lightsAdded) {
  const ambient = new THREE.AmbientLight(0xffffff, 1.55);
  const key = new THREE.DirectionalLight(0xffffff, 2.65);
  key.position.set(-3.5, 4.2, 5.5);
  const fill = new THREE.DirectionalLight(0x85ffff, 1.05);
  fill.position.set(3.5, -1.0, 3.0);
  scene.add(ambient, key, fill);
  FIG.lightsAdded = true;
}

const SOLIDS = [
  {
    name: 'Right circular cylinder',
    short: 'Right circular cylinder',
    letter: '(a)',
    body: 'A rectangular region with one side on the axis of revolution sweeps out a true right circular cylinder.'
  },
  {
    name: 'Solid sphere',
    short: 'Solid sphere',
    letter: '(b)',
    body: 'A semicircular region revolved about its diameter fills a solid sphere.'
  },
  {
    name: 'Solid cone',
    short: 'Solid cone',
    letter: '(c)',
    body: 'A triangular region revolved about one leg forms a true solid cone.'
  },
  {
    name: 'Hollowed right circular cylinder',
    short: 'Hollowed right<br>circular cylinder',
    letter: '(d)',
    body: 'An offset rectangular region revolved about the axis creates a cylindrical shell: a hollowed right circular cylinder.'
  }
];

const PANEL_X = [-3.42, -1.14, 1.14, 3.42];
const TOP_Y = 1.10;
const SOLID_Y = -0.48;
const CAPTION_Y = -1.55;
const LETTER_Y = -2.02;

function basicMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: opacity >= 1
  });
}

function phongMat(color, opacity = 1, opts = {}) {
  return new THREE.MeshPhongMaterial({
    color,
    specular: opts.specular ?? 0xf4ffff,
    shininess: opts.shininess ?? 54,
    transparent: opacity < 1,
    opacity,
    side: opts.side ?? THREE.DoubleSide,
    depthWrite: opts.depthWrite ?? opacity >= 0.96
  });
}

function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
}

function makeLine(points, color = FIG.dark, closed = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  return closed ? new THREE.LineLoop(geom, lineMat(color, opacity)) : new THREE.Line(geom, lineMat(color, opacity));
}

function rectMesh(cx, cy, w, h, color, opacity = 1, z = 0) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), basicMat(color, opacity));
  mesh.position.set(cx, cy, z);
  return mesh;
}

function rectLine(cx, cy, w, h, color = FIG.gray, z = 0.01) {
  return makeLine([
    new THREE.Vector3(cx - w / 2, cy - h / 2, z),
    new THREE.Vector3(cx + w / 2, cy - h / 2, z),
    new THREE.Vector3(cx + w / 2, cy + h / 2, z),
    new THREE.Vector3(cx - w / 2, cy + h / 2, z)
  ], color, true);
}

function shapeMesh(shape, color, opacity = 1, z = 0) {
  const mesh = new THREE.Mesh(new THREE.ShapeGeometry(shape), basicMat(color, opacity));
  mesh.position.z = z;
  return mesh;
}

function ellipseShape(cx, cy, rx, ry) {
  const s = new THREE.Shape();
  s.absellipse(cx, cy, rx, ry, 0, Math.PI * 2, false, 0);
  return s;
}

function circleLineYZ(x, r, color = FIG.teal, opacity = 1, segments = 128) {
  const pts = [];
  for (let i = 0; i < segments; i++) {
    const a = Math.PI * 2 * i / segments;
    pts.push(new THREE.Vector3(x, r * Math.cos(a), r * Math.sin(a)));
  }
  return makeLine(pts, color, true, opacity);
}

function circleArcYZ(x, r, a0, a1, color = FIG.teal, opacity = 1, segments = 56) {
  const pts = [];
  for (let i = 0; i <= segments; i++) {
    const a = a0 + (a1 - a0) * i / segments;
    pts.push(new THREE.Vector3(x, r * Math.cos(a), r * Math.sin(a)));
  }
  return makeLine(pts, color, false, opacity);
}

function rectProfileShape(x0, x1, y0, y1) {
  const s = new THREE.Shape();
  s.moveTo(x0, y0);
  s.lineTo(x1, y0);
  s.lineTo(x1, y1);
  s.lineTo(x0, y1);
  s.lineTo(x0, y0);
  return s;
}

function triangleMesh(points2, color, opacity = 1, z = 0) {
  const s = new THREE.Shape();
  s.moveTo(points2[0][0], points2[0][1]);
  for (let i = 1; i < points2.length; i++) s.lineTo(points2[i][0], points2[i][1]);
  s.lineTo(points2[0][0], points2[0][1]);
  return shapeMesh(s, color, opacity, z);
}

function addFigLabel(html, pos, opts = {}) {
  const e = addLabel(html, pos, opts);
  FIG.labels.push(e);
  return e;
}

function clearFigure() {
  FIG.root.clear();
  for (const entry of FIG.labels) {
    entry.div.remove();
    const idx = _labels.indexOf(entry);
    if (idx >= 0) _labels.splice(idx, 1);
  }
  FIG.labels = [];
  if (typeof _interactiveObjects !== 'undefined') _interactiveObjects.length = 0;
  FIG.animGhost = null;
}

function makeRotationArrowLocal() {
  const g = new THREE.Group();
  const cx = 0.91, cy = 0.0, rx = 0.075, ry = 0.30;
  const pts = [];
  for (let i = 0; i <= 82; i++) {
    const a = -1.35 * Math.PI + 1.78 * Math.PI * (i / 82);
    pts.push(new THREE.Vector3(cx + rx * Math.cos(a), cy + ry * Math.sin(a), 0.026));
  }
  g.add(makeLine(pts, FIG.dark, false));
  const head = new THREE.Shape();
  head.moveTo(cx + 0.038, cy - 0.155);
  head.lineTo(cx + 0.122, cy - 0.252);
  head.lineTo(cx + 0.020, cy - 0.218);
  head.lineTo(cx + 0.038, cy - 0.155);
  g.add(shapeMesh(head, FIG.dark, 1, 0.031));
  return g;
}

function makeTopAxis() {
  return makeLine([
    new THREE.Vector3(-1.08, 0, 0.02),
    new THREE.Vector3(1.10, 0, 0.02)
  ], FIG.dark);
}

function profileRegion(type, opacity = 0.76, outlineOpacity = 1) {
  const g = new THREE.Group();

  if (type === 'Right circular cylinder') {
    const s = rectProfileShape(-0.74, 0.74, 0, 0.72);
    g.add(shapeMesh(s, FIG.pale, opacity, 0.01));
    g.add(makeLine([
      new THREE.Vector3(-0.74, 0, 0.04),
      new THREE.Vector3(0.74, 0, 0.04),
      new THREE.Vector3(0.74, 0.72, 0.04),
      new THREE.Vector3(-0.74, 0.72, 0.04)
    ], FIG.teal, true, outlineOpacity));
  }

  if (type === 'Solid sphere') {
    const r = 0.72;
    const s = new THREE.Shape();
    s.moveTo(-r, 0);
    for (let i = 0; i <= 88; i++) {
      const a = Math.PI - Math.PI * i / 88;
      s.lineTo(r * Math.cos(a), r * Math.sin(a));
    }
    s.lineTo(-r, 0);
    g.add(shapeMesh(s, FIG.pale, opacity, 0.01));
    const pts = [];
    for (let i = 0; i <= 88; i++) {
      const a = Math.PI - Math.PI * i / 88;
      pts.push(new THREE.Vector3(r * Math.cos(a), r * Math.sin(a), 0.04));
    }
    pts.push(new THREE.Vector3(-r, 0, 0.04));
    g.add(makeLine(pts, FIG.teal, false, outlineOpacity));
  }

  if (type === 'Solid cone') {
    g.add(triangleMesh([[-0.78, 0], [0.76, 0], [0.76, 0.72]], FIG.pale, opacity, 0.01));
    g.add(makeLine([
      new THREE.Vector3(-0.78, 0, 0.04),
      new THREE.Vector3(0.76, 0, 0.04),
      new THREE.Vector3(0.76, 0.72, 0.04)
    ], FIG.teal, true, outlineOpacity));
  }

  if (type === 'Hollowed right circular cylinder') {
    const s = rectProfileShape(-0.74, 0.74, 0.42, 0.72);
    g.add(shapeMesh(s, FIG.pale, opacity, 0.01));
    g.add(makeLine([
      new THREE.Vector3(-0.74, 0.42, 0.04),
      new THREE.Vector3(0.74, 0.42, 0.04),
      new THREE.Vector3(0.74, 0.72, 0.04),
      new THREE.Vector3(-0.74, 0.72, 0.04)
    ], FIG.teal, true, outlineOpacity));
  }

  return g;
}

function topPanel(type, index) {
  const g = new THREE.Group();
  g.position.set(PANEL_X[index], TOP_Y, 0);
  g.add(makeTopAxis());
  g.add(profileRegion(type));
  g.add(makeRotationArrowLocal());

  if (type === FIG.selected && FIG.animating) {
    const ghostAngles = [Math.PI / 4, Math.PI / 2, 3 * Math.PI / 4];
    ghostAngles.forEach(a => {
      const ghost = profileRegion(type, 0.13, 0.30);
      ghost.rotation.x = a;
      g.add(ghost);
    });
    FIG.animGhost = profileRegion(type, 0.36, 0.95);
    FIG.animGhost.position.z = 0.085;
    g.add(FIG.animGhost);
  }

  return g;
}

function solidAxis(y = 0, z = 0.50, length = 1.92) {
  return makeLine([
    new THREE.Vector3(-length / 2, y, z),
    new THREE.Vector3(length / 2, y, z)
  ], FIG.dark, false, 0.96);
}

function capDisk(x, r, mat, normalSign = 1) {
  const cap = new THREE.Mesh(new THREE.CircleGeometry(r, 128), mat);
  cap.rotation.y = normalSign > 0 ? Math.PI / 2 : -Math.PI / 2;
  cap.position.x = x;
  return cap;
}

function cylinderSolid() {
  const g = new THREE.Group();
  const L = 1.52, R = 0.46;

  const side = new THREE.Mesh(
    new THREE.CylinderGeometry(R, R, L, 128, 1, true),
    phongMat(FIG.cyan, 0.74, { shininess: 70, depthWrite: false })
  );
  side.rotation.z = Math.PI / 2;
  g.add(side);

  const leftCap = capDisk(-L / 2, R, phongMat(0x55cbd0, 0.58, { shininess: 45, depthWrite: false }), -1);
  const rightCap = capDisk(L / 2, R, phongMat(0xd3efed, 0.86, { shininess: 55, depthWrite: false }), 1);
  g.add(leftCap, rightCap);

  g.add(circleLineYZ(-L / 2, R, FIG.teal, 0.45));
  g.add(circleLineYZ(L / 2, R, FIG.teal, 1));
  g.add(makeLine([new THREE.Vector3(-L / 2, R, 0), new THREE.Vector3(L / 2, R, 0)], FIG.teal, false, 0.28));
  g.add(makeLine([new THREE.Vector3(-L / 2, -R, 0), new THREE.Vector3(L / 2, -R, 0)], FIG.teal, false, 0.20));
  g.add(solidAxis(0, 0.52));
  return g;
}

function sphereSolid() {
  const g = new THREE.Group();
  const R = 0.62;
  const sphere = new THREE.Mesh(
    new THREE.SphereGeometry(R, 128, 64),
    phongMat(FIG.cyan, 0.94, { shininess: 84, depthWrite: true })
  );
  g.add(sphere);

  const highlight = new THREE.Mesh(
    new THREE.CircleGeometry(0.16, 48),
    basicMat(0xffffff, 0.20)
  );
  highlight.position.set(-0.25, 0.26, 0.55);
  highlight.scale.set(1.28, 0.72, 1);
  g.add(highlight);

  g.add(solidAxis(0, 0.64, 1.92));
  return g;
}

function coneSolid() {
  const g = new THREE.Group();
  const L = 1.52, R = 0.46;

  const side = new THREE.Mesh(
    new THREE.ConeGeometry(R, L, 128, 1, true),
    phongMat(FIG.cyan, 0.76, { shininess: 72, depthWrite: false })
  );
  side.rotation.z = Math.PI / 2;
  g.add(side);

  const cap = capDisk(L / 2, R, phongMat(0xd4efee, 0.83, { shininess: 52, depthWrite: false }), 1);
  g.add(cap);

  g.add(circleLineYZ(L / 2, R, FIG.teal, 1));
  g.add(makeLine([new THREE.Vector3(-L / 2, 0, 0), new THREE.Vector3(L / 2, R, 0)], FIG.teal, false, 0.88));
  g.add(makeLine([new THREE.Vector3(-L / 2, 0, 0), new THREE.Vector3(L / 2, -R, 0)], FIG.teal, false, 0.64));
  g.add(solidAxis(0, 0.50, 1.92));
  return g;
}

function ringCap(x, innerR, outerR, mat, normalSign = 1) {
  const ring = new THREE.Mesh(new THREE.RingGeometry(innerR, outerR, 128, 2), mat);
  ring.rotation.y = normalSign > 0 ? Math.PI / 2 : -Math.PI / 2;
  ring.position.x = x;
  return ring;
}

function hollowCylinderSolid() {
  const g = new THREE.Group();
  const L = 1.52, Ro = 0.46, Ri = 0.23;

  const outerSide = new THREE.Mesh(
    new THREE.CylinderGeometry(Ro, Ro, L, 128, 1, true),
    phongMat(FIG.cyan, 0.66, { shininess: 68, depthWrite: false })
  );
  outerSide.rotation.z = Math.PI / 2;
  g.add(outerSide);

  const innerSide = new THREE.Mesh(
    new THREE.CylinderGeometry(Ri, Ri, L * 1.01, 128, 1, true),
    phongMat(FIG.cyanDark, 0.46, { shininess: 40, side: THREE.BackSide, depthWrite: false })
  );
  innerSide.rotation.z = Math.PI / 2;
  g.add(innerSide);

  const leftRing = ringCap(-L / 2, Ri, Ro, phongMat(0xccebea, 0.58, { shininess: 46, depthWrite: false }), -1);
  const rightRing = ringCap(L / 2, Ri, Ro, phongMat(0xd8f0ef, 0.90, { shininess: 56, depthWrite: false }), 1);
  g.add(leftRing, rightRing);

  g.add(circleLineYZ(-L / 2, Ro, FIG.teal, 0.38));
  g.add(circleLineYZ(L / 2, Ro, FIG.teal, 1));
  g.add(circleLineYZ(-L / 2, Ri, FIG.teal, 0.34));
  g.add(circleLineYZ(L / 2, Ri, FIG.teal, 0.96));
  g.add(makeLine([new THREE.Vector3(-L / 2, Ro, 0), new THREE.Vector3(L / 2, Ro, 0)], FIG.teal, false, 0.22));
  g.add(makeLine([new THREE.Vector3(-L / 2, -Ro, 0), new THREE.Vector3(L / 2, -Ro, 0)], FIG.teal, false, 0.18));
  g.add(solidAxis(0, 0.52));
  return g;
}

function solidPanel(type, index) {
  const g = new THREE.Group();
  g.position.set(PANEL_X[index], SOLID_Y, 0);
  if (type === 'Right circular cylinder') g.add(cylinderSolid());
  if (type === 'Solid sphere') g.add(sphereSolid());
  if (type === 'Solid cone') g.add(coneSolid());
  if (type === 'Hollowed right circular cylinder') g.add(hollowCylinderSolid());
  return g;
}

function captionBox(index, info) {
  const g = new THREE.Group();
  const w = info.name === 'Right circular cylinder' ? 1.96
    : info.name === 'Hollowed right circular cylinder' ? 1.68
      : info.name === 'Solid sphere' ? 1.28 : 1.18;
  const h = info.name === 'Hollowed right circular cylinder' ? 0.64 : 0.38;
  g.add(rectMesh(PANEL_X[index], CAPTION_Y, w, h, 0xffffff, 0.985, 0.0));
  g.add(rectLine(PANEL_X[index], CAPTION_Y, w, h, FIG.gray, 0.045));
  return g;
}

function addLabels() {
  addFigLabel('Some Familiar Solids of Revolution', new THREE.Vector3(0, 2.18, 0), {
    fontSize: '32px',
    color: FIG.charcoal
  });

  addFigLabel('Axis of revolution', new THREE.Vector3(PANEL_X[0] - 0.82, TOP_Y - 0.30, 0), {
    fontSize: '27px',
    color: FIG.charcoal,
    offset: [-46, 12]
  });

  SOLIDS.forEach((info, i) => {
    addFigLabel(info.short, new THREE.Vector3(PANEL_X[i], CAPTION_Y, 0), {
      fontSize: info.name === 'Hollowed right circular cylinder' ? '24px' : '25px',
      color: FIG.charcoal
    });
    addFigLabel(`<i>${info.letter}</i>`, new THREE.Vector3(PANEL_X[i], LETTER_Y, 0), {
      fontSize: '30px',
      color: '#111'
    });
  });
}

function addPanelHitArea(info, index) {
  const hit = rectMesh(PANEL_X[index], 0.00, 2.02, 3.55, 0xffffff, 0.001, 0.92);
  hit.material.depthWrite = false;
  FIG.root.add(hit);
  registerInteractive(hit, {
    title: info.name,
    tooltip: `Click to focus ${info.letter}`,
    body: info.body,
    onClick: () => {
      setSolid(info.name);
      showPopup(info.name, info.body);
    }
  });
}

function addBoundsForFit() {
  const m = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, depthWrite: false });
  [
    [-4.32, -2.22, -0.72], [4.32, -2.22, 0.72],
    [-4.32, 2.36, -0.72], [4.32, 2.36, 0.72]
  ].forEach(p => {
    const b = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.025, 0.025), m);
    b.position.set(p[0], p[1], p[2]);
    FIG.root.add(b);
  });
}

function buildFigure() {
  clearFigure();

  SOLIDS.forEach((info, i) => {
    FIG.root.add(topPanel(info.name, i));
    FIG.root.add(solidPanel(info.name, i));
    FIG.root.add(captionBox(i, info));
  });

  SOLIDS.forEach((info, i) => addPanelHitArea(info, i));
  addBoundsForFit();

  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 80,
    elevationDeg: 0,
    target: [0, 0.02, 0],
    heightFraction: 0.90,
    distanceScale: 1.5
  });

  addLabels();
  updateUiState();
}

function updateUiState() {
  const solidSel = document.getElementById('solidType');
  const animSel = document.getElementById('rotationAnimation');
  if (solidSel) solidSel.value = FIG.selected;
  if (animSel) animSel.value = FIG.animating ? 'On' : 'Off';
  for (let i = 0; i < 4; i++) {
    const btn = document.getElementById(`step${i}`);
    if (btn) btn.classList.toggle('active', SOLIDS[i].name === FIG.selected);
  }
}

function setSolid(name) {
  FIG.selected = name;
  buildFigure();
}

function setAnimation(on) {
  FIG.animating = !!on;
  buildFigure();
}

document.getElementById('solidType').addEventListener('change', e => setSolid(e.target.value));
document.getElementById('rotationAnimation').addEventListener('change', e => setAnimation(e.target.value === 'On'));

function goToStep(i) {
  const idx = Math.max(0, Math.min(SOLIDS.length - 1, i | 0));
  FIG.selected = SOLIDS[idx].name;
  FIG.animating = true;
  buildFigure();
  showPopup(SOLIDS[idx].name, SOLIDS[idx].body);
}

for (let i = 0; i < 4; i++) {
  document.getElementById(`step${i}`).addEventListener('click', () => goToStep(i));
}

function updateRevolutionAnimation() {
  requestAnimationFrame(updateRevolutionAnimation);
  if (!FIG.animating || !FIG.animGhost) return;
  FIG.theta += 0.045;
  FIG.animGhost.rotation.x = FIG.theta;
}

controls.enableRotate = true;
controls.enablePan = true;
controls.enableZoom = true;

buildFigure();
updateRevolutionAnimation();
// @FIGURE_CODE_END

